          49: "5지를 펴서 밖으로 구부린 왼 주먹 등을 손끝이 왼쪽으로 향하게 편 오른 손바닥으로 두 번 두드린 다음, 두 손을 펴서 손가락이 아래를 향하게 하여 배에 댔다가 위로 스쳐 올린다.",
          50: "5지를 펴서 밖으로 구부린 왼 주먹 등을 손끝이 왼쪽으로 향하게 편 오른 손바닥으로 두 번 두드린 다음, 두 주먹을 앞으로 올려 떠는 동작을 한다.",
