        descriptions: {
          1: "가슴 앞에서 두 주먹을, 손목을 돌리며 밖으로 엇갈리게 크게 돌린다.",
          2: "가슴 앞에서 두 주먹을, 손목을 돌리며 밖으로 엇갈리게 크게 돌린 다음, 손바닥이 아래로 향하게 반쯤 구부린 오른손을 가슴 앞에서 약간 내리다가 멈춘다.",
          3: "두 손을 약간 구부려 손가락 끝을 양쪽 뺨에 댔다가 밖으로 길게 내밀며 손가락 끝이 밖으로 향하게 한다.",
          4: "두 손의 손가락을 약간 구부려 두 볼에 댔다가 약간 내리며 손바닥이 밖으로 향하게 돌린 다음, 손끝이 밖으로 향하게 편 두 손의 5지를 맞대고 나머지 손가락을 상하로 두 번 흔든다.",
          5: "왼손의 1·5지로 코를 잡고 왼팔 사이로, 주먹을 쥔 오른팔을 넣어 좌우로 흔든다.",
          6: "오른손의 2·3·5지 끝 바닥을 맞대고 세운 오른팔의 팔꿈치를 왼 손바닥으로 받치고 오른팔을 전후로 두 번 움직인다.",
          7: "오른손 5지를 접고 나머지 손가락을 펴서 손끝이 왼쪽을 향하고 손등이 바깥쪽을 향하게 한 후, 왼쪽 팔에 반원을 두번 안쪽으로 그린다.",
          8: "오른 주먹의 바닥을 입 앞에 대고 왼쪽으로 두 바퀴 돌린다.",
          9: "가볍게 쥔 두 주먹을, 바닥이 밖으로 향하게 하여 머리 양쪽에 대고 교대로 올리면서 1·2지를 벌려 편다.",
          10: "1지를 펴서 구부린 두 주먹을 머리 양쪽에 댔다가 원을 그리며 밖으로 내민다.",
          11: "두 주먹의 1·5지를 펴서 1지 끝이 위로 향하게 하여 5지 끝을 머리 양쪽에 댄다.",
          12: "오른 주먹을 1·5지 옆면이 턱에 닿게 대고 전후로 움직인다.",
          13: "1지를 펴서 구부린 오른 주먹의 손목 안쪽을 코에 댄다.",
          14: "오른손의 1·5지 끝을 맞대어 동그라미를 만들어, 손바닥이 밖으로 향하게 하여 코앞에서 왼쪽으로 두 바퀴 돌린다.",
          15: "1지를 펴서 약간 구부린 두 주먹의 4지 옆면을 맞대어 입 앞에 댄다.",
          16: "두 손을 자연스럽게 펴서 손바닥이 밖으로 손끝이 위로 향하게 세워 두 5지 끝을 머리 양쪽에 대고 두 손의 1·2·3·4지를 전후로 약간 흔든다.",
          17: "오른 주먹의 1·5지를 펴고 1지 끝으로 입 오른쪽에서부터 귀 뒤로 두 번 스쳐 낸다.",
          18: "5지와 2·3지 끝을 맞대고 1·4지를 펴서 세운 오른손을 손등이 입으로 향하게 하여 입 앞에서 왼쪽으로 두 바퀴 돌린다.",
          19: "오른 주먹의 5지를 펴서 등이 입으로 향하게 하여 입 왼쪽으로 두 바퀴 돌린다.",
          20: "왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 세우고, 그 등에 오른 주먹의 1·2지를 펴서 등을 대고 구부렸다 폈다 한다.",
          21: "왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 하고, 그 등을 오른 손바닥으로 덮은 다음, 왼 주먹의 5지를 두번 구부렸다 편다.",
          22: "오른 주먹의 1·2·5지를 펴서 약간 구부려 손등을 입 앞에 대고 손끝을 두 번 붙였다 뗀다.",
          23: "손바닥이 아래로 향하게 편 왼손 밑으로, 5지를 펴서 세운 오른 주먹을 좌우로 흔들며 내민다.",
          24: "오른 주먹을 입 앞에 댔다가 1·2지를 펴며, 좌우로 흔들며 빠르게 약간 위로 내민다.",
          25: "손끝이 밖으로 손바닥이 위로 향하게 손가락을 붙인 왼손에 손가락을 붙인 오른손을 댔다가 크게 벌렸다가 다시 맞댄다.",
          26: "오른 주먹의 1·2지를 펴서 바닥으로 오른뺨을 두 번 스쳐 낸다.",
          27: "두 주먹의 바닥으로 양쪽 가슴을 두 번 번갈아 힘차게 두드린다.",
          28: "오른손을 펴서 세워 5지를 이마에 대고 나머지 손가락을 좌우로 약간 흔든다.",
          29: "오른 주먹의 1·5지를 펴서 손등을 입 앞에 대고 1·5지 끝을 붙인 다음, 두 손을 옆으로 벌려 상하로 흔든다.",
          30: "오른손을 반쯤 구부리고 왼 손등으로 팔꿈치를 받쳐 세운 오른팔을 전후로 움직인다.",
          31: "오른 주먹의 1지를 약간 구부려 끝이 밖으로 향하게 하여 등을 입에 댄 다음, 두 손을 벌려 상하로 흔든다.",
          32: "오른손의 3·5지를 접고 나머지 손가락을 펴서 포물선을 그리며 빠르게 왼쪽으로 내민다.",
          33: "오른손의 2지 끝을 오른뺨에 댔다가 펴고 손바닥으로 오른뺨을 살짝 때린다.",
          34: "오른손을 펴서 손끝이 위로 손바닥이 입으로 향하게 하여, 입 앞에서 왼쪽으로 돌린 다음, 오른쪽 볼에 오른손의 2지 끝을 댔다 떼고, 손바닥을 살짝 댄다.",
          35: "두 주먹의 1·2·5지를 펴서 두 5지 끝을 맞대고 1·2지를 동시에 상하로 흔든다.",
          36: "손끝이 밖으로 향하게 편 두 손의 5지를 맞대고 나머지 손가락을 상하로 두 번 흔든다.",
          37: "오른손을 구부려 오른쪽 귀 둘레에 대었다가 앞으로 두 번 내민다.",
          38: "오른 주먹의 4지를 펴서 등이 위로 끝이 왼쪽으로 향하게 하여 구부렸다 폈다 하며 왼쪽으로 움직인다.",
          39: "오른 손바닥으로 머리 오른쪽을 스쳐 내린 다음, 오른 주먹의 4지를 펴서 등이 위로 끝이 왼쪽으로 향하게 하여 구부렸다 폈다 하면서 왼쪽으로 움직인다.",
          40: "오른 손바닥으로 머리 오른쪽을 스쳐 내린 다음, 오른 주먹의 4지를 펴서 구부렸다 폈다 하면서 왼쪽으로 돌린다.",
          41: "손끝이 밖으로 향하게 펴서 모로 세운 오른손을 좌우로 움직이며 밖으로 내민다.",
          42: "두 주먹의 바닥으로 배를 번갈아 두 번 두드린다.",
          43: "손등이 위로 손끝이 오른쪽으로 향하게 편 왼손의 1지 옆면에 오른손을 펴서 손바닥이 왼쪽으로 향하게 대고 밖으로 내민다.",
          44: "오른 손목 등을 턱에 대고 자연스럽게 벌려 내려뜨린 오른손의 손가락을 따로 따로 움직인다.",
          45: "오른 주먹의 1지를 펴서 끝을 왼 손바닥에 댔다가 위로 튕기면서 굽히는 동작을 두 번 반복한다.",
          46: "손가락을 붙인 왼 손가락 끝을, 손바닥이 아래로 향한 오른 손등에 대고 오른 손가락을 번갈아 움직인다."
        },
