          69: "오른 주먹의 1·2지를 펴서 끝이 왼쪽으로 향하게 하여 바닥을 턱에 댔다가 이마에 댄 다음, 두 주먹의 1·5지를 펴서 끝이 밖으로 향하게 하여 두 번 벌렸다 붙이며 양옆으로 벌린다.",
