          48: "오른 주먹의 1지를 펴서 끝을 오른쪽 관자놀이에 댄 다음,두 주먹의 1·5지를 펴서 끝이 옆으로 향하게 하여 오른 주먹의 5지 끝으로 왼 주먹의 1·5지 끝을 두 번 스쳐낸다.",
