          21: "손끝이 위로 손등이 밖으로 향하게 세운 왼 손끝 위에서 오른 주먹의 1지를 펴서 왼쪽에서 오른쪽으로 이동시킨 다음, 오른 주먹의 1·5지로 왼손의 2지를 집었다가 놓으며 올려 1·5지 끝을 맞댄다.",
          22: "오른 주먹의 1지를 펴서 반쯤 구부려 끝으로 머리 오른쪽을 두 번 친 다음, 손끝이 왼쪽으로 손등이 위로 향하게 편 오른손의 1지 옆면으로 코밑을 오른쪽으로 스쳐 낸다.",
          23: "두 주먹의 1지를 펴서 끝이 밖으로 바닥이 위로 향하게 하였다가 바닥이 아래로 향하게 중앙으로 반원을 그리며 돌려 맞댄 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          24: "오른 주먹의 1지를 펴서 옆면으로 입술 밑을 오른쪽으로 스쳐 낸 다음, 왼 손바닥을, 오른",
