          45: "왼손을 펴서 손바닥이 아래로 손끝이 밖으로 향하게 하고, 그 밑에서 오른손을 약간 구부려 모로 세워 왼팔의 팔꿈치 쪽으로 당기며 주먹을 쥔다.",
          46: "왼 주먹의 5지를 펴서 세우고 그 위를 손가락이 아래로 향하게 구부린 오른손으로 내리 덮으며 동시에 약간 내린다.",
          47: "오른손을 약간 구부려 오른쪽 어깨에 올려 놓은 다음, 5지를 펴서 세운 왼 주먹 밑에, 5지를 펴서 세운 오른 주먹을 댄다.",
          48: "왼 주먹의 5지를 펴서 세우고,그 위에 손등이 위로 향하게 약간 구부린 오른손을 덮듯이 올려 동시에 돌린후 오른 주먹 1·2지를 펴서 약간 구부려 끝이 눈으로 향하게 하여 왼쪽으로 돌린 다음, 펴서 세운 오른손을, 5지를 펴서 세운 왼 주먹을 감싸듯이 오른쪽에서 왼쪽으로 돌린다.",
          49: "두 손을 구부려 머리 양쪽에 대고 좌우로 돌린다.",
          50: "손바닥이 위로 향하게 편 왼 손바닥에 오른 손의 손가락을 벌려 올려 놓았다가 들어 올리면서 손가락 끝을 모은다.",
          51: "손가락을 벌려 반쯤 구부리고 손등이 위로 향하게 편 두 손의 손가락 등을 두 번 부딪친다.",
          52: "두 손을 약간 구부려 양쪽 가슴에 대고 상하로 동시에 움직인 다음, 오른 주먹을 아래로 당긴다.",
          53: "약간 구부린 오른손을 오른쪽 어깨에 올려놓은 다음, 오른 주먹을 쥐며 5지를 펴서 바닥이 밖으로 향하게 내 세운다.",
          54: "오른손을 약간 구부려 끝으로 가슴을 두 번 두드린다.",
          55: "손바닥이 왼쪽으로 손가락이 밖으로 향하게 편 오른손을 안으로 강하고 빠르게 당기며 주먹을 쥔다.",
          56: "손등이 밖으로 향하게 쥔 오른손을 가슴 약간 위쪽에, 손등이 안으로 향하게 쥔 왼손을 가슴 약간 아래쪽에 세웠다가 오른쪽으로 이동하며 손목을 돌려 손등의 방향이 반대가 되게 하며 주먹을 쥔다.",
          57: "반쯤 구부린 두 손의 손가락을 서로 끼우며 상하로 돌린다.",
          58: "두 손을 약간 구부려 상하로 마주 보게 하여 좌우로 엇갈리게 돌린다.",
          59: "두 손의 손바닥이 상하로 마주보게 하였다가 좌우로 엇갈리게 약간 돌리며 주먹을 쥐고 맞댄다.",
          60: "오른손으로 왼 손바닥 위에 있는 물건을 밖으로 잡아채는 동작을 한다.",
          61: "손가락을 벌려 반쯤 구부리고 손등이 위로 향하게 편 두 손의 손가락 등을 오른손이 안쪽에 놓이게 전후로 마주대고 밖으로 밀어낸다.",
          62: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔든 다음, 왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 세우고, 그 등에 오른 손바닥을 세워 두 번 대고, 두 주먹의 바닥을 오른쪽 가슴에 오른 주먹이 위에 놓이게 이어 댄다.",
          63: "배 앞에서 두 손을 약간 구부려 상하로 마주보게 하였다가 주먹을 쥐며 맞댄다.",
          64: "오른손을 약간 구부려 끝이 코끝으로 향하게 하여 좌우로 움직인 다음, 왼 주먹의 4지를 펴서 등이 밖으로 향하게 세우고, 그 옆면을 오른 손바닥으로 두 번 스쳐 올린다.",
          65: "오른손을 약간 구부려 끝이 코끝으로 향하게 하여 좌우로 움직인 다음, 왼 주먹의 4지를 펴서 등이 밖으로 향하게 펴서 세우고 그 안쪽에서 오른 주먹을 좌우로 두 번 흔든다.",
          66: "약간 구부린 오른 손끝을 가슴에 대고 왼쪽으로 강하게 천천히 두 바퀴 돌린다.",
          67: "손가락을 벌려 약간 구부린 오른손으로 얼굴을 가렸다가 손바닥이 오른쪽으로 향하게 돌리는 동작을 한 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 벌린다.",
          68: "약간 구부린 두 손을 양쪽 어깨에 올려놓는다.",
          69: "손바닥이 옆으로 손 끝이 위로 향하게 펴서 약간 구부린 두 손을 얼굴 양옆에 세워 마주 보게 하여 가볍게 좌우로 두 번 흔든 다음, 두 주먹의 1·2·5지를 펴서 구부려 끝이 마주보게 하여 안으로 당긴다.",
          70: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔든 다음, 오른손을, 손바닥이 위로 향하게 하여 약간 구부렸다가 위로 올리며 주먹을 쥔다.",
          71: "주먹을 쥔 왼 주먹 등에 오른손의 4지 옆으로 대고 위로 빠르게 스쳐 올리며 주먹을 쥔다.",
          72: "두 손을 구부려 벌려 머리 위에서 좌우로 두 번 움직인다.",
          73: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔들고, 5지를 펴서 세운 두 주먹을 마주 보게 하여 두 번 약간 굽혔다가 세운 다음, 손바닥이 아래로 향하게 반쯤 구부린 오른손을 가슴 앞에서 약간 내리다가 멈춘다.",
          74: "손등이 위로 손끝이 밖으로 향하게 편 두 손의 손가락을 번갈아 움직인 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          75: "손등이 위로 손끝이 밖으로 향하게 편 두 손의 손가락을 번갈아 움직인다.",
          76: "오른손의 손가락을 벌려 반쯤 구부려 입 가까이 대고 두 번 돌린 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 벌린다.",
          77: "왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 세우고 그 등을, 약간 구부린 오른 손끝으로 두 번 긁어내린다.",
          78: "오른손을 약간 구부려 끝이 코끝으로 향하게 하여 좌우로 움직인다.",
          79: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔든 다음, 5지 바닥을 1지 옆면에 대고 손등이 왼쪽으로 향하게 모로 세운 왼 주먹 위에 오른 손바닥을 대고 오른손만 오른쪽으로 돌리고, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          80: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔든 다음, 오른손을 펴서 손끝이 위로 향하게 하여 5지 옆면을 왼쪽 가슴에 댔다가 오른쪽 가슴에 대고, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          81: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔든 다음, 왼손을 손바닥이 아래로 향하게 하고, 오른 주먹의 5지를 펴서 세워 왼 손바닥 밑을 스쳐 밖으로 내민다.",
          82: "손가락을 벌려 구부린 양손을 마주 보게 하여 전후로 돌린 다음, 손끝이 위로 향하게 구부린 두 손의 손가락 등을 가슴 앞에서 마주 댔다가 양옆으로 벌린다.",
          83: "두 손을 구부려 끝을 배에 댔다가 가슴으로 힘주어 올려 손바닥이 위로 향하게 한다.",
          84: "오른손을 구부려 바닥이 위로 향하게 하여 왼쪽에서 오른쪽으로 움직인다.",
          85: "손가락을 벌려 반쯤 구부리고 손등이 위로 향하게 편 두 손의 손가락 등을 두 번 부딪친 다음, 손바닥이 아래로 향하게 반쯤 구부린 오른손을 가슴 앞에서 약간 내리다가 멈춘다.",
