          88: "손바닥이 위로 향하게 편 왼 손바닥에 손가락을 약간 구부려 바닥이 아래로 향하게 편 오른손을 왼 손바닥 밑에서부터 힘주어 올려 손등이 닿게 돌려 댄다.",
          89: "오른손의 손가락을 벌려 반쯤 구부려 입 가까이 대고 두 번 돌린다.",
          90: "구부린 두 손의 손바닥이 안으로 향하게 하여 깍지 끼우고 좌우로 움직인다.",
          91: "왼손을 손바닥이 위로 손끝이 밖으로 향하게 하고, 오른손을 손끝이 아래로 향하게 구부려 왼손 위에 올려두었다가 안으로 끌어들이며 오른손을 주먹 쥔다.",
          92: "두 손을 약간 구부려 끝을 왼쪽 어깨 앞에 댔다가 내리며 두 손을 벌리며 활짝 편다.",
          93: "약간 구부린 오른 손끝을 가슴에 대고 왼쪽으로 한 바퀴 돌린 다음, 왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 세우고, 그 등에 손바닥이 위로 향하게 편 오른 손끝을 두 번 댄다.",
          94: "두 손을 약간 구부려 손바닥이 아래로 향하게 하여 가슴 앞에서 오른쪽으로 한 바퀴 돌린다.",
          95: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔든 다음, 5지를 펴서 세운 두 주먹을 상하로 엇갈리게 두 번 움직인다.",
          96: "두 손의 손가락을 약간 구부려 마주 보게 세워 전후로 약간 흔든다.",
