          102: "오른손을 구부려 ‘C’자 모양이 되게 한 다음, 4·5지를 접고 그 위에 1·2·3지를 접어 댄다.",
          103: "5지와 나머지 손가락 사이를 벌려 ‘ㄷ’ 모양이 되게 하여 5지가 아래에 놓이게 한 오른손을, 같은 모양의 왼손의 5지 밑에 댔다가 왼 손등에 올려놓고, 왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 세우고, 오른 주먹의 1지를 펴서 끝이 왼 주먹의 5지 등으로 향하게 하여 좌우로 두 번 흔든다.",
          104: "손 끝이 위로 손등이 바깥으로 향하게 새운 왼 손바닥을, 오른 손바닥으로 감싸 왼손을 따라 올리며 오른손 1지를 편다.",
          105: "주먹을 쥔 왼 팔을 세우고, 오른손으로 왼팔의 위팔을 감아 돌린 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          106: "주먹을 쥔 왼 팔을 세우고, 오른손으로 왼팔의 위팔을 감아 돌린다.",
