          109: "두 손의 손가락을 반쯤 구부려 오른손이 위에 왼손이 아래에 놓이게 하여 끼운 다음, 손끝이 밖으로 향하게 모로 세운 왼 손바닥 앞에서, 손등이 밖으로 손끝이 왼 손바닥으로 향하게 편 오른손을 꺾어 내린다.",
