          131: "오른 주먹의 등으로, 왼 손바닥을 힘껏 치며 손목을 약간 돌린다.",
          132: "오른 주먹의 1·5지 옆면을 턱에 대고 전후로 흔든 다음, 손바닥이 아래로 향하게 반쯤 구부린 오른손을 가슴 앞에서 약간 내리다가 멈춘다.",
          133: "왼손으로 주먹을 쥔 오른팔을 잡았다가 오른팔을 수직으로 내려 오른 손목을 잡게 한 다음, 오른 주먹의 4지를 펴서 끝을 오른쪽 입가에 댄다.",
          134: "왼손으로 오른 주먹의 손목을 잡고 그 주먹을 구부려 입으로 내리며 머리를 약간 뒤로 젖히고 입을 벌린다.",
          135: "모로 세운 왼 주먹 위를 주먹 쥔 오른손으로 좌우로 스친다.",
          136: "왼손으로 주먹을 쥔 오른 주먹의 손목을 잡고 오른 주먹을 천천히 약간 숙인다.",
          137: "두 주먹의 손목을 상하로 마주 댄다.",
          138: "모로 세운 왼 주먹에 모로 세운 오른 주먹을 올려놓고 왼쪽으로 두 바퀴 돌린다.",
          139: "4지 옆면이 밖으로 향하게 가볍게 쥔 오른주먹을 얼굴 오른쪽에서 얼굴 앞으로 재빠르게 돌리며 활짝 펴서 얼굴을 가린다.",
          140: "양 주먹을 쥐고 팔을 구부려 당겼다가 손가락을 펴면서 아래로 힘없이 내린다.",
          141: "두 주먹을, 오른 주먹이 위에 놓이게 상하로 이어대고 이마 위로 올렸다가 밖으로 내리치는 동작을 두 번 반복한다.",
