          143: "오른쪽 어깨 앞에서 두 주먹을 상하로 이어대고 윗몸을 오른쪽으로 약간 기울인다.",
          144: "손바닥이 위로 향하게 편 왼 손바닥에 오른 주먹을 모로 세우고 왼쪽으로 돌린 다음, 오른 주먹의 1·2지를 펴서 바닥이 왼쪽으로 향하게 세워 이마에 댄다.",
