          155: "오른 주먹의 4지 옆면을 배 왼쪽에 댔다가 오른쪽으로 이동한다",
          156: "오른 주먹을 코에 1·5지 옆면이 닿게 댄 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          157: "왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 세우고, 그 왼쪽과 오른쪽을 오른 주먹으로 때리는 동작을 한다.",
          158: "손바닥이 위로 향하게 편 왼 손바닥에 오른 주먹을 모로 세워 왼쪽으로 돌린다.",
          159: "두 주먹을 상하로 엇갈리게 스친 다음, 손바닥이 왼쪽으로 향하게 펴서 세운 오른 팔꿈치를 왼 손바닥으로 받치고 전후로 두 번 흔들고, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          160: "왼 주먹 위에 오른 주먹을 대고 두 주먹을 함께 올린 다음, 손바닥이 아래로 향하게 반쯤 구부린 오른손을 가슴 앞에서 약간 내리다가 멈춘다.",
          161: "오른 주먹의 바닥을 코데 댔다가 손목을 돌려 손등을 코에 댄다.",
          162: "두 주먹을 오른쪽 가슴에 오른 주먹이 위에 놓이게 이어 댄 다음, 오른 주먹의 1·2지를 펴서 끝으로 왼쪽 가슴에 처음에는 왼쪽에서 오른쪽으로, 다음에는 위쪽에서 아래쪽으로 선을 긋는다.",
          163: "두 주먹을 번갈아 서로 다른 주먹 위로 올린 다음, 손바닥이 아래로 향하게 반쯤 구부린 오른 손을 가슴 앞에서 약간 내리다가 멈춘다.",
          164: "오른 주먹의 1·5지 쪽을 왼뺨에 댄 다음, 반쯤 구부린 오른손의 1·5지 옆면을 눈 앞에 대고 손가락을 두 번 구부렸다 편다.",
          165: "두 주먹을 양어깨 높이에서 두 번 위로 올렸다 내린 다음, 손등이 아래로 향하게 가볍게 쥔 두 주먹을 위로 올리며 손가락을 활짝 편다.",
          166: "두 주먹을 어깨 앞에서 아래로 내리다 멈춘 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 두 번 약간 돌리며 벌린다.",
          167: "두 주먹을 가슴 앞으로 올려 떠는 동작을 한 다음, 손바닥이 아래로 향하게 반쯤 구부린 오른손을 가슴 앞에서 약간 내리다가 멈춘다.",
          168: "오른 주먹으로 주먹을 쥔 왼 팔등을 두드린 다음, 오른손의 1·5지 끝을 맞대어 동그라미를 만든다.",
          169: "모로 세운 왼 주먹의 손목을 모로 세운 오른 주먹으로 친 다음, 오른 주먹의 5지를 펴서 오른쪽 어깨 뒤쪽으로 힘주어 젖힌다.",
          170: "두 주먹을 오른쪽 가슴에 오른 주먹이 위에 놓이게 상하로 이어 댄 다음, 두 손의 4지 옆면을 비스듬히 맞대어 밖으로 내밀고, 오른 주먹의 5지를 펴서 왼 손바닥에 세운다.",
          171: "두 주먹을 1·5지 옆면이 닿게 맞댔다가 손가락이 밑으로 향하게 벌리며 비스듬히 내린다.",
          172: "두 주먹을 바닥이 마주 보게 하여 상하로 엇갈리게 움직인다.",
          173: "두 주먹을 오른쪽 어깨 위에 오른 주먹의 4지 옆면이 왼 주먹의 1지 옆면에 닿게 대고 밖으로 내밀면서 동시에 손을 편다.",
          174: "두 주먹의 바닥을 오른쪽 가슴에 오른 주먹이 위에 놓이게 이어 댄 다음, 두 손의 손끝을 마주 댔다가 안으로 원을 그리며 돌려 두 손목을 맞댄다.",
          175: "가슴 앞에서 두 주먹을, 손목을 돌리며 밖으로 엇갈리게 크게 돌린 다음, 둥글게 구부린 왼손을 손바닥이 위로 향하게 올리고, 그 안쪽에서 오른 주먹의 1·5지를 펴서 1지 끝이 밖으로 향하게 모로 세워 1지를 구부리고, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 벌린다.",
          176: "오른 주먹의 손목 등을 코에 대고 돌리고, 오른손의 1·5지 끝을 맞대어 동그라미를 만들어 왼 손바닥으로 내리며 1·5지를 편다.",
          177: "오른 주먹으로, 주먹을 쥔 왼 팔등을 두 번 두드린 다음, 두 주먹의 1지를 펴서 끝이 옆으로 향하게 모로 세워 오른손이 위에 놓이게 상하로 놓고 두 손을 동시에 위로 올린다.",
          178: "주먹을 쥔 오른 팔꿈치를 오른쪽 옆구리에 댔다가 옆으로 올린다.",
          179: "두 손을 둥글게 쥐고 상하로 마주 보게 하였다가 바깥으로 내밀며 손가락을 모두 편 다음, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 벌린다.",
          180: "모로 세운 왼 주먹을 향하여 오른 주먹을 밖으로 돌려 내린 다음, 왼손을 손바닥이 아래로 향하게 하고, 그 등에 오른 손바닥을 대고 밖으로 약간 누른다.",
          181: "두 주먹의 바닥을 오른쪽 가슴에 오른 주먹이 위에 놓이게 이어 댄 다음, 오른 주먹의 4·5지를 펴서 손등이 위로 향하게 하여 왼쪽 위로 내민다.",
          182: "모로 세운 왼 주먹의 손등에 오른 주먹의 1지를 펴서 끝을 댔다가 떼며 손가락을 2·3·4지 순으로 편다.",
          183: "두 주먹의 손목을 ‘X’자로 댔다가 양옆으로 벌리며 손목을 돌려 바닥이 밖으로 향하게 한다.",
          184: "손등이 위로 향하게 쥔 두 주먹을 가슴 앞에서 맞댔다가 밖으로 벌려 내밀며 활짝 편다.",
          185: "오른 주먹을 오른쪽 귀 밑에서 1·2·5지를 튕기며 밖으로 내민다.",
          186: "손등이 위로 향하게 쥔 두 주먹을 양쪽 가슴 앞에서 마주 보게 하여 상하로 엇갈리게 흔든다.",
          187: "손등이 위로 향하게 쥔 두 주먹을 전후로 엇갈리게 움직인 다음, 왼 주먹의 5지를 펴서 바닥이 밖으로 향하게 세우고, 그 등에 오른 손바닥을 세워 대고, 두 주먹의 4·5지를 펴서 끝이 위로 향하게 맞대고 세워 양옆으로 벌린다.",
          188: "가볍게 쥔 오른 주먹을 모로 세워 둥글게 돌린다.",
